export function clearFashionPreview(event: SyntheticEvent<HTMLImageElement>): void { const image=event.currentTarget, source=image.currentSrc, requested=image.getAttribute('src'); const clear=()=>{if(image.isConnected && image.currentSrc===source && image.getAttribute('src')===requested && image.complete && image.naturalWidth) image.style.backgroundImage='none';}; if(typeof image.decode==='function') void image.decode().then(clear).catch(clear); else clear(); }
